CREATE DATABASE IF NOT EXISTS travelgo;
USE travelgo;
CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('USER','ADMIN') NOT NULL DEFAULT 'USER', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS destinations (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, country VARCHAR(120) NOT NULL, description TEXT, image_url VARCHAR(500), starting_price DECIMAL(12,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hotels (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, destination_id BIGINT NOT NULL, description TEXT, price_per_night DECIMAL(12,2) NOT NULL, rating DECIMAL(2,1) NOT NULL, image_url VARCHAR(500), location VARCHAR(255), amenities TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(destination_id) REFERENCES destinations(id));
CREATE TABLE IF NOT EXISTS travel_packages (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, destination_id BIGINT NOT NULL, description TEXT, duration VARCHAR(80) NOT NULL, price DECIMAL(12,2) NOT NULL, image_url VARCHAR(500), included_services TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(destination_id) REFERENCES destinations(id));
CREATE TABLE IF NOT EXISTS bookings (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, package_id BIGINT NOT NULL, room_type VARCHAR(40) NOT NULL, travel_date DATE NOT NULL, guests INT NOT NULL, total_amount DECIMAL(12,2) NOT NULL, status ENUM('PENDING','CONFIRMED','CANCELLED','COMPLETED') NOT NULL DEFAULT 'PENDING', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(package_id) REFERENCES travel_packages(id));
CREATE INDEX idx_bookings_user ON bookings(user_id);
